import{_ as p,a0 as i,w as g,s as u,I as o,x as n,a1 as e,A as r,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"11 个使用 GNOME 3 桌面环境的理由 | LCTT x X-CMD","titleTemplate":false,"description":"11 个使用 GNOME 3 桌面环境的理由 | LCTT (201708) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"11 个使用 GNOME 3 桌面环境的理由 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"11 个使用 GNOME 3 桌面环境的理由 | LCTT (201708) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201708/20170529 11 reasons to use the GNOME 3 desktop environment for Linux","title":"11 个使用 GNOME 3 桌面环境的理由","tag":"201708","desc":""},"relativePath":"201708/20170529 11 reasons to use the GNOME 3 desktop environment for Linux.md","filePath":"[post].md"}'),d={name:"201708/20170529 11 reasons to use the GNOME 3 desktop environment for Linux.md"};function m(a,t,f,N,M,E){const s=i("Link");return g(),u("div",null,[t[32]||(t[32]=o("h1",{id:"_11-个使用-gnome-3-桌面环境的理由",tabindex:"-1"},[n("11 个使用 GNOME 3 桌面环境的理由 "),o("a",{class:"header-anchor",href:"#_11-个使用-gnome-3-桌面环境的理由","aria-label":"Permalink to “11 个使用 GNOME 3 桌面环境的理由”"},"​")],-1)),t[33]||(t[33]=o("blockquote",null,[o("p",null,"GNOME 3 桌面的设计目的是简单、易于访问和可靠。GNOME 的受欢迎程度证明达成了这些目标。")],-1)),t[34]||(t[34]=o("p",null,[o("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/custom_gnomes.png?itok=iG98iL8d",alt:"11 reasons to use the GNOME desktop environment",title:"11 reasons to use the GNOME desktop environment"})],-1)),o("p",null,[t[1]||(t[1]=n("去年年底，在我升级到 Fedora 25 后，新版本 ",-1)),e(s,{href:"https://opensource.com/life/15/4/9-reasons-to-use-kde"},{default:r(()=>[...t[0]||(t[0]=[n("KDE",-1)])]),_:1}),t[2]||(t[2]=n(" Plasma 出现了一些问题，这使我难以完成任何工作。所以我决定尝试其他的 Linux 桌面环境有两个原因。首先，我需要完成我的工作。第二，多年来一直使用 KDE，我想可能是尝试一些不同的桌面的时候了。",-1))]),o("p",null,[t[6]||(t[6]=n("我尝试了几个星期的第一个替代桌面是我在 1 月份文章中写到的 ",-1)),e(s,{href:"https://linux.cn/article-8606-1.html"},{default:r(()=>[...t[3]||(t[3]=[n("Cinnamon",-1)])]),_:1}),t[7]||(t[7]=n("，然后我写了用了大约八个星期的",-1)),e(s,{href:"https://linux.cn/article-8434-1.html"},{default:r(()=>[...t[4]||(t[4]=[n("LXDE",-1)])]),_:1}),t[8]||(t[8]=n("，我发现这里有很多事情我都喜欢。我用了 ",-1)),e(s,{href:"https://www.gnome.org/gnome-3/"},{default:r(()=>[...t[5]||(t[5]=[n("GNOME 3",-1)])]),_:1}),t[9]||(t[9]=n(" 几个星期来写了这篇文章。",-1))]),t[35]||(t[35]=l('<p>像几乎所有的网络世界一样，GNOME 是缩写；它代表 “GNU 网络对象模型”（GNU Network Object Model）。GNOME 3 桌面设计的目的是简单、易于访问和可靠。GNOME 的受欢迎程度证明达成了这些目标。</p><p>GNOME 3 在需要大量屏幕空间的环境中非常有用。这意味着两个具有高分辨率的大屏幕，并最大限度地减少桌面小部件、面板和用来启动新程序之类任务的图标所需的空间。GNOME 项目有一套人机接口指南（HIG），用来定义人类应该如何与计算机交互的 GNOME 哲学。</p><h3 id="我使用-gnome-3-的十一个原因" tabindex="-1">我使用 GNOME 3 的十一个原因 <a class="header-anchor" href="#我使用-gnome-3-的十一个原因" aria-label="Permalink to “我使用 GNOME 3 的十一个原因”">​</a></h3><p>1、 <strong>诸多选择：</strong> GNOME 以多种形式出现在我个人喜爱的 Fedora 等一些发行版上。你可以选择的桌面登录选项有 GNOME Classic、Xorg 上的 GNOME、GNOME 和 GNOME（Wayland）。从表面上看，启动后这些都是一样的，但它们使用不同的 X 服务器，或者使用不同的工具包构建。Wayland 在小细节上提供了更多的功能，例如动态滚动，拖放和中键粘贴。</p><p>2、 <strong>入门教程：</strong> 在用户第一次登录时会显示入门教程。它向你展示了如何执行常见任务，并提供了大量的帮助链接。教程在首次启动后关闭后也可轻松访问，以便随时访问该教程。教程非常简单直观，这为 GNOME 新用户提供了一个简单明了开始。要之后返回本教程，请点击 <strong>Activities</strong>，然后点击会显示程序的有九个点的正方形。然后找到并点击标为救生员图标的 <strong>Help</strong>。</p><p>3、 <strong>桌面整洁：</strong> 对桌面环境采用极简方法以减少杂乱，GNOME 设计为仅提供具备可用环境所必需的最低限度。你应该只能看到顶部栏（是的，它就叫这个），其他所有的都被隐藏，直到需要才显示。目的是允许用户专注于手头的任务，并尽量减少桌面上其他东西造成的干扰。</p><p>4、 <strong>顶部栏：</strong> 无论你想做什么，顶部栏总是开始的地方。你可以启动应用程序、注销、关闭电源、启动或停止网络等。不管你想做什么都很简单。除了当前应用程序之外，顶栏通常是桌面上唯一的其他对象。</p><p>5、 <strong>dash：</strong> 如下所示，在默认情况下, dash 包含三个图标。在开始使用应用程序时，会将它们添加到 dash 中，以便在其中显示最常用的应用程序。你也可以从应用程序查看器中将应用程序图标添加到 dash 中。</p><p><img src="https://opensource.com/sites/default/files/images/life-uploads/gnome_fig_2.png" alt="gnome_fig_2.png"></p><p>6、 <strong>应用程序浏览器：</strong> 我真的很喜欢这个可以从位于 GNOME 桌面左侧的垂直条上访问应用程序浏览器。除非有一个正在运行的程序，GNOME 桌面通常没有任何东西，所以你必须点击顶部栏上的 <strong>Activities</strong> 选区，点击 dash 底部的九个点组成的正方形，它是应用程序浏览器的图标。</p><p><img src="https://opensource.com/sites/default/files/images/life-uploads/gnome_fig_1.png" alt="gnome_fig_1.png"></p><p>如上所示，浏览器本身是一个由已安装的应用程序的图标组成的矩阵。矩阵下方有一对互斥的按钮，<strong>Frequent</strong> 和 <strong>All</strong>。默认情况下，应用程序浏览器会显示所有安装的应用。点击 <strong>Frequent</strong> 按钮，它会只显示最常用的应用程序。向上和向下滚动以找到要启动的应用程序。应用程序按名称按字母顺序显示。</p>',12)),o("p",null,[e(s,{href:"https://www.gnome.org/gnome-3/"},{default:r(()=>[...t[10]||(t[10]=[n("GNOME",-1)])]),_:1}),t[11]||(t[11]=n(" 官网和内置的帮助有更多关于浏览器的细节。",-1))]),t[36]||(t[36]=l('<p>7、 <strong>应用程序就绪通知：</strong> 当新启动的应用程序的窗口打开并准备就绪时，GNOME 会在屏幕顶部显示一个整齐的通知。只需点击通知即可切换到该窗口。与在其他桌面上搜索新打开的应用程序窗口相比，这节省了一些时间。</p><p>8、 <strong>应用程序显示：</strong> 为了访问不可见的其它运行的应用程序，点击 <strong>Activities</strong> 菜单。这将在桌面上的矩阵中显示所有正在运行的应用程序。点击所需的应用程序将其带到前台。虽然当前应用程序显示在顶栏中，但其他正在运行的应用程序不会。</p><p>9、 <strong>最小的窗口装饰：</strong> 桌面上打开窗口也很简单。标题栏上唯一显示的按钮是关闭窗口的 “X”。所有其他功能，如最小化、最大化、移动到另一个桌面等，可以通过在标题栏上右键单击来访问。</p><p>10、 <strong>自动创建的新桌面：</strong> 在使用下一空桌面的时候将自动创建的新的空桌面。这意味着总是有一个空的桌面在需要时可以使用。我使用的所有其他的桌面系统都可以让你在桌面活动时设置桌面数量，但必须使用系统设置手动完成。</p><p>11、 <strong>兼容性：</strong> 与我所使用的所有其他桌面一样，为其他桌面创建的应用程序可在 GNOME 上正常工作。这功能让我有可能测试这些桌面，以便我可以写出它们。</p><h3 id="最后的思考" tabindex="-1">最后的思考 <a class="header-anchor" href="#最后的思考" aria-label="Permalink to “最后的思考”">​</a></h3><p>GNOME 不像我以前用过的桌面。它的主要指导是“简单”。其他一切都要以简单易用为前提。如果你从入门教程开始，学习如何使用 GNOME 需要很少的时间。这并不意味着 GNOME 有所不足。它是一款始终保持不变的功能强大且灵活的桌面。</p>',7)),o("p",null,[t[15]||(t[15]=n("（题图：",-1)),e(s,{href:"https://pixabay.com/en/users/karpartenhund-3077375/"},{default:r(()=>[...t[12]||(t[12]=[n("Gunnar Wortmann",-1)])]),_:1}),t[16]||(t[16]=n(" 通过 ",-1)),e(s,{href:"https://pixabay.com/en/garden-gnome-black-and-white-f%C3%B6hr-1584401/"},{default:r(()=>[...t[13]||(t[13]=[n("Pixabay",-1)])]),_:1}),t[17]||(t[17]=n("。由 Opensource.com 修改。",-1)),e(s,{href:"https://creativecommons.org/licenses/by-sa/4.0/"},{default:r(()=>[...t[14]||(t[14]=[n("CC BY-SA 4.0",-1)])]),_:1}),t[18]||(t[18]=n("）",-1))]),t[37]||(t[37]=o("hr",null,null,-1)),t[38]||(t[38]=o("p",null,"作者简介：",-1)),t[39]||(t[39]=o("p",null,"David Both - David Both 是位于北卡罗来纳州罗利的 Linux 和开源倡导者。他已经在 IT 行业工作了四十多年，并为 IBM 教授 OS/2 超过 20 年。在 IBM，他在 1981 年为初始的 IBM PC 写了第一个培训课程。他为红帽教授 RHCE 课程，曾在 MCI Worldcom、思科和北卡罗来纳州工作。他一直在使用 Linux 和开源软件近 20 年。",-1)),t[40]||(t[40]=o("hr",null,null,-1)),o("p",null,[t[20]||(t[20]=n("via: ",-1)),e(s,{href:"https://opensource.com/article/17/5/reasons-gnome"},{default:r(()=>[...t[19]||(t[19]=[n("https://opensource.com/article/17/5/reasons-gnome",-1)])]),_:1})]),o("p",null,[t[24]||(t[24]=n("作者：",-1)),e(s,{href:"https://opensource.com/users/dboth"},{default:r(()=>[...t[21]||(t[21]=[n("David Both",-1)])]),_:1}),t[25]||(t[25]=n(" 译者：",-1)),e(s,{href:"https://github.com/geekpi"},{default:r(()=>[...t[22]||(t[22]=[n("geekpi",-1)])]),_:1}),t[26]||(t[26]=n(" 校对：",-1)),e(s,{href:"https://github.com/wxy"},{default:r(()=>[...t[23]||(t[23]=[n("wxy",-1)])]),_:1})]),o("p",null,[t[29]||(t[29]=n("本文由 ",-1)),e(s,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[27]||(t[27]=[n("LCTT",-1)])]),_:1}),t[30]||(t[30]=n(" 原创编译，",-1)),e(s,{href:"https://linux.cn/"},{default:r(()=>[...t[28]||(t[28]=[n("Linux中国",-1)])]),_:1}),t[31]||(t[31]=n(" 荣誉推出",-1))])])}const x=p(d,[["render",m]]);export{T as __pageData,x as default};
